// T-519 item 2: the OBSERVER's line in ATTESTATION (paragraph 5): the entry's whole text by the lead daemon's
// SPIRITS class (daemons_spirits.h: 0 as it is, 1 good spirits, 2 low spirits).
#define UNITY_OBSERVER_ENTRY 0
static const u8 sUnityObserver_1[] = _("The shadows and the light are but two halves of the same horizon. This book was torn at the spine and is whole again. It was written for no hour. Open it whenever you like.\pOne half was read in the dark by a hatter, and one at first light by a lark. Each was sure the other had the bad half. Each was right about what it saw, and wrong about what it was holding. You have read both, which nobody else has.\pThe halves said the same things in two voices. This book says them once, and is quieter for it. The words in green are not for saying loudly or softly: mean them.\pIs any of it true?\pTake it with a grain of salt, and hold it lightly. Then ask what it would change, and what it would give.\pYour daemon sits with you, bright, and patient as the stone.");
static const u8 sUnityObserver_2[] = _("The shadows and the light are but two halves of the same horizon. This book was torn at the spine and is whole again. It was written for no hour. Open it whenever you like.\pOne half was read in the dark by a hatter, and one at first light by a lark. Each was sure the other had the bad half. Each was right about what it saw, and wrong about what it was holding. You have read both, which nobody else has.\pThe halves said the same things in two voices. This book says them once, and is quieter for it. The words in green are not for saying loudly or softly: mean them.\pIs any of it true?\pTake it with a grain of salt, and hold it lightly. Then ask what it would change, and what it would give.\pYour daemon sits with you. That is enough to start with.");
static const u8 *const sUnityObserver[3] = { sUnityText_0, sUnityObserver_1, sUnityObserver_2 };
